<include file="Public:header"/><div class="mainbox">	<div id="nav" class="mainnav_title">		<ul>			<a href="{pigcms{:U('Recruit/position_list')}">职位列表</a>|			<a href="{pigcms{:U('Recruit/position_category')}" class="on">职位分类管理</a>		</ul>	</div>	<div>		<input type="button" value="添加职位分类" class="button" onclick="window.o2oTop.artiframe('{pigcms{:U('position_category_edit',array('fid'=>$_GET['fid']))}','添加职位分类',800,480,true,false,false,addbtn,'add',true);"/>	</div>	<form name="myform" id="myform" action="" method="post" frame="true" refresh="true">		<div class="table-list">			<table width="100%" cellspacing="0">				<thead>					<tr>						<th>编号</th>						<th>名称</th>						<th>等级</th>						<th>是否隐藏</th>						<if condition="!$_GET['fid']">						<th>下级分类</th>						</if>						<th>操作</th>					</tr>				</thead>				<tbody>					<if condition="$list">						<volist name="list" id="vo">							<tr>								<td>{pigcms{$vo.id}</td>								<td>{pigcms{$vo.name}</td>								<td>{pigcms{$vo.level}</td>								<td>                                <if condition="$vo['is_hide'] eq 1">                                	<span style="color: red;">是</span>                                <else/>                                	<span style="color: green;">否</span>                                </if>                            	</td>								<if condition="!$_GET['fid']">								<td><a href="{pigcms{:U('Recruit/position_category',array('fid'=>$vo['id']))}">查看</a></td>								</if>								<td>									<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('position_category_edit',array('id'=>$vo['id'],'fid'=>$vo['fid']))}','编辑',600,500,true,false,false,editbtn,'edit',true);">编辑</a>|									<!-- <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('position_category_del')}">删除</a> -->							  	</td>							</tr>						</volist>						<tr><td class="textcenter pagebar" colspan="15">{pigcms{$list.pagebar}</td></tr>					<else/>						<tr><td class="textcenter red" colspan="16">列表为空！</td></tr>					</if>				</tbody>			</table>		</div>	</form></div><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script><include file="Public:footer"/>